package com.cbdog.ptvbox

import okhttp3.*
import okhttp3.HttpUrl.Companion.toHttpUrl
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

data class Subtitle053(val provider:String,val id:String,val title:String,val detail:String="",val url:String="",val pack:Boolean=false){val archive get()=pack||url.substringBefore('?').endsWith(".zip",true)||title.endsWith(".zip",true)||provider=="SubDL";val key get()="$provider:$id";fun json()=JSONObject().put("provider",provider).put("id",id).put("title",title).put("detail",detail).put("url",url).put("pack",pack);companion object{fun from(j:JSONObject)=Subtitle053(j.getString("provider"),j.getString("id"),j.getString("title"),j.optString("detail"),j.optString("url"),j.optBoolean("pack"))}}
/** Credentials belong only to the service host, never to redirects or subtitle CDNs. No response/body/URL logging. */
class OnlineSubtitles053(private val secrets:SecretStore,private val client:OkHttpClient=NetworkPolicy.client().newBuilder().protocols(listOf(Protocol.HTTP_1_1)).callTimeout(22,TimeUnit.SECONDS).followRedirects(false).retryOnConnectionFailure(false).build()) {
 private val ua="Ptvbox v${BuildConfig.VERSION_NAME}"
 private fun bytes(url:String,headers:Map<String,String> = emptyMap(),body:JSONObject?=null,phase:String="请求",limit:Int=10_000_000):ByteArray {var target=url.toHttpUrl();var h=headers;repeat(6){val builder=Request.Builder().url(target).header("User-Agent",ua);h.forEach{(k,v)->builder.header(k,v)};if(body!=null)builder.post(body.toString().toRequestBody("application/json".toMediaType()));client.newCall(builder.build()).execute().use{r->if(r.code in 300..399){require(body==null){"$phase 不接受POST重定向"};val next=target.resolve(r.header("Location").orEmpty())?:throw IOException("$phase 重定向无效");require(next.isHttps){"$phase 拒绝非HTTPS下载"};if(next.host!=target.host)h=emptyMap();target=next;return@repeat};if(!r.isSuccessful){val kind=if(r.header("Content-Type").orEmpty().contains("json"))"API"else"网关/CDN";throw IOException("$phase HTTP ${r.code}（$kind）"+(r.header("Retry-After")?.take(20)?.let{"，请等待${it}后重试"}?:""))};val out=java.io.ByteArrayOutputStream();r.body.byteStream().use{input->val buf=ByteArray(8192);while(true){val n=input.read(buf);if(n<0)break;require(out.size()+n<=limit){"$phase 返回文件过大"};out.write(buf,0,n)}};return out.toByteArray()}};throw IOException("$phase 重定向过多")}
 private fun json(url:String,h:Map<String,String> = emptyMap(),body:JSONObject?=null,phase:String="搜索")=try{JSONObject(bytes(url,h,body,phase,4_000_000).toString(Charsets.UTF_8))}catch(e:org.json.JSONException){throw IOException("$phase 返回非JSON内容，可能是登录页或网关故障")}
 private fun url(root:String,params:Map<String,String>)=root.toHttpUrl().newBuilder().apply{params.forEach{(k,v)->if(v.isNotBlank())addQueryParameter(k,v)}}.build().toString()
 fun configured()=listOf("OpenSubtitles V3")+listOf("subdl" to "SubDL","assrt" to "ASSRT","opensub_key" to "OpenSubtitles").filter{secrets.read(it.first).isNotBlank()}.map{it.second}
 fun searchExpanded(provider:String,c:MediaContext053):List<Subtitle053>{val first=search(provider,c);if(first.isNotEmpty()||c.tmdbId.isNotBlank()||c.work.facts.imdbId.isNotBlank())return first;val alternate=c.names.drop(1).firstOrNull()?:return first;if(provider=="ASSRT")Thread.sleep(3100);return search(provider,c.copy(work=c.work.copy(title=alternate,original="",aliases=emptyList())))}
 fun search(provider:String,c:MediaContext053):List<Subtitle053> = when(provider){
  "OpenSubtitles V3"->{val imdb=c.work.facts.imdbId.takeIf{it.startsWith("tt")}?:return emptyList();val route=if(c.work.kind=="tv")"series/$imdb:${c.work.season}:${c.episode?:1}.json" else "movie/$imdb.json";val j=json("https://opensubtitles-v3.strem.io/subtitles/$route",mapOf("User-Agent" to "Stremio/1.6.0","Accept" to "application/json"),phase="公共字幕搜索");j.optJSONArray("subtitles")?.objects().orEmpty().filter{it.optString("lang").lowercase() in setOf("chi","zho","zh","chs","cht")}.map{r->Subtitle053("OpenSubtitles V3",r.optString("id"),r.optString("subtitleFileName",r.optString("movieReleaseName","中文字幕")),r.optString("lang")+" · 公共无需Key",r.optString("url"))}.filter{it.id.isNotBlank()&&it.url.startsWith("https://")}}
  "SubDL"->{val key=secrets.read("subdl");val p=mutableMapOf("api_key" to key,"languages" to "ZH","type" to if(c.work.kind=="tv")"tv"else"movie","subs_per_page" to "30","releases" to "1","unpack" to "1");when{c.tmdbId.isNotBlank()->p["tmdb_id"]=c.tmdbId;c.work.facts.imdbId.isNotBlank()->p["imdb_id"]=c.work.facts.imdbId;else->p["film_name"]=c.names.first()};if(c.work.kind=="tv"){p["season_number"]=c.work.season.toString();c.episode?.let{p["episode_number"]=it.toString()}}else p["year"]=c.work.year;val j=json(url("https://api.subdl.com/api/v1/subtitles",p));if(!j.optBoolean("status"))throw IOException("SubDL 未返回字幕，请核对Key或作品信息");j.optJSONArray("subtitles")?.objects().orEmpty().filter{c.accepts(it.optString("release_name"),it.optInt("season",0),it.optInt("episode",0))}.mapNotNull{r->val link=r.optString("url");val u="https://dl.subdl.com".toHttpUrl().resolve(link);if(u==null||u.host!="dl.subdl.com")null else Subtitle053("SubDL",r.optString("subtitlePage",link),r.optString("release_name","中文字幕"),r.optString("language")+" · "+r.optString("fps"),u.toString())}}
  "ASSRT"->{val h=mapOf("Authorization" to "Bearer ${secrets.read("assrt")}");val query=c.names.first()+if(c.work.kind=="tv"&&c.episode!=null)" S%02dE%02d".format(c.work.season,c.episode)else" ${c.work.year}";val j=json(url("https://api.assrt.net/v1/sub/search",mapOf("q" to query.trim(),"filelist" to "1","cnt" to "15")),h);if(j.optInt("status")!=0)throw IOException("ASSRT 搜索失败，状态${j.optInt("status")}");j.optJSONObject("sub")?.optJSONArray("subs")?.objects().orEmpty().filter{c.accepts(it.optString("native_name")+" "+it.optString("videoname"))}.map{r->Subtitle053("ASSRT",r.optString("id"),r.optString("native_name").ifBlank{r.optString("videoname")},r.optJSONObject("lang")?.optString("desc").orEmpty()+" · 字幕包",pack=true)}}
  "OpenSubtitles"->{val p=mutableMapOf("languages" to "zh-cn,zh-tw","type" to if(c.work.kind=="tv")"episode"else"movie","order_by" to "download_count","order_direction" to "desc");if(c.tmdbId.isNotBlank())p[if(c.work.kind=="tv")"parent_tmdb_id"else"tmdb_id"]=c.tmdbId else if(c.work.facts.imdbId.isNotBlank())p[if(c.work.kind=="tv")"parent_imdb_id"else"imdb_id"]=c.work.facts.imdbId.removePrefix("tt")else p["query"]=c.names.first();if(c.work.kind=="tv"){p["season_number"]=c.work.season.toString();c.episode?.let{p["episode_number"]=it.toString()}}else p["year"]=c.work.year;val j=json(url("https://api.opensubtitles.com/api/v1/subtitles",p),osHeaders());j.optJSONArray("data")?.objects().orEmpty().flatMap{r->val a=r.optJSONObject("attributes")?:JSONObject();val f=a.optJSONObject("feature_details")?:JSONObject();val title=a.optString("release");val identity=f.optString("title");if(c.tmdbId.isBlank()&&c.work.facts.imdbId.isBlank()&&identity.isNotBlank()&&!c.exactName(identity)||!c.accepts(title,f.optInt("season_number"),f.optInt("episode_number")))emptyList()else a.optJSONArray("files")?.objects().orEmpty().mapNotNull{file->val id=file.optLong("file_id");if(id<=0)null else Subtitle053("OpenSubtitles",id.toString(),file.optString("file_name").ifBlank{title},a.optString("language")+" · "+a.optString("fps"))}}}
  else->emptyList()
 }
 fun files(s:Subtitle053,c:MediaContext053):List<Subtitle053>{if(!s.pack)return listOf(s);val j=json(url("https://api.assrt.net/v1/sub/detail",mapOf("id" to s.id)),mapOf("Authorization" to "Bearer ${secrets.read("assrt")}"),phase="ASSRT字幕包详情");val row=j.optJSONObject("sub")?.optJSONArray("subs")?.optJSONObject(0)?:throw IOException("字幕包详情为空");val files=row.optJSONArray("filelist")?.objects().orEmpty().mapNotNull{f->val name=f.optString("f");val link=f.optString("url");if(link.isBlank()||!c.accepts(name))null else Subtitle053("ASSRT",s.id+":"+name,name,s.detail,link.replace("http://","https://"))};return files.ifEmpty{val link=row.optString("url");if(link.isBlank())emptyList()else listOf(s.copy(url=link.replace("http://","https://"),pack=false))}}
 private fun osHeaders()=mapOf("Api-Key" to secrets.read("opensub_key"),"Accept" to "application/json")
 fun download(s:Subtitle053):List<Pair<String,String>> {val link=if(s.provider=="OpenSubtitles"){
  require(secrets.read("opensub_user").isNotBlank()&&secrets.read("opensub_password").isNotBlank()){"请先配置OpenSubtitles账号及密码"}
  val login=json("https://api.opensubtitles.com/api/v1/login",osHeaders(),JSONObject().put("username",secrets.read("opensub_user")).put("password",secrets.read("opensub_password")),"OpenSubtitles登录");val token=login.optString("token");require(token.isNotBlank()){"OpenSubtitles登录未返回授权"};val host=login.optString("base_url").ifBlank{"api.opensubtitles.com"}.removePrefix("https://").trimEnd('/');require(host.matches(Regex("[a-zA-Z0-9.-]+"))&&(host=="api.opensubtitles.com"||host.endsWith(".opensubtitles.com"))){"登录返回的服务主机不受信任"};val headers=osHeaders()+mapOf("Authorization" to "Bearer $token");val info=json("https://$host/api/v1/infos/user",headers,phase="OpenSubtitles账号信息");require(info.optJSONObject("data")!=null){"OpenSubtitles账号信息未通过"};json("https://$host/api/v1/download",headers,JSONObject().put("file_id",s.id.toLong()).put("sub_format","srt"),"OpenSubtitles获取下载链接").getString("link")
 }else s.url;val u=link.toHttpUrl();require(u.isHttps){"拒绝非HTTPS字幕下载"};return MediaText053.unpack(bytes(link,phase="字幕文件下载"),s.title)}
}
